/* amirsalmani/primitives — label, link, button, glass, figure.
 *
 * Requires tokens.css. Every colour derives from the local --fg/--bg; there is
 * no hex in this file and there must never be one.
 *
 * The rule that makes the type cohere (brand.md §3): sans is for what a human
 * wrote, mono is for what a machine would emit. Mono therefore carries — and
 * only carries — labels, indices, keys, source lines and button text.
 */

/* ── label ── the eyebrow, section number, status key and source line ───── */
.as-label {
  font-family: var(--mono);
  font-size: .7rem;
  font-weight: 500;
  letter-spacing: .18em;
  text-transform: uppercase;
  color: var(--muted);
}
.as-label--faint { color: var(--faint); }

/* ── link ── underline at 40%, going solid. Never a colour change. ──────── */
.as-link {
  color: inherit;
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: .22em;
  text-decoration-color: color-mix(in srgb, currentColor 40%, transparent);
  transition: text-decoration-color var(--fast) var(--ease-out), color var(--fast) var(--ease-out);
}
.as-link:hover, .as-link:focus-visible { color: var(--accent); text-decoration-color: currentColor; }

/* ── glass ── a floating functional layer, never a mood. Never stack two. ─ */
.as-glass {
  position: relative;
  background: var(--glass);
  border: 1px solid var(--glass-edge);
  border-radius: var(--radius);
  -webkit-backdrop-filter: blur(22px) saturate(150%);
          backdrop-filter: blur(22px) saturate(150%);
}
.as-glass::before {                 /* light catching the top edge */
  content: "";
  position: absolute;
  inset: 0 0 auto 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--glass-top) 22%, var(--glass-top) 78%, transparent);
  pointer-events: none;
}

/* ── button ── emphasis by inversion, because there is no accent hue ─────── */
.as-btn {
  display: inline-flex;
  align-items: center;
  gap: .625rem;
  padding: .875rem 1.5rem;
  border: 1px solid var(--glass-edge);
  border-radius: 999px;
  background: var(--glass);
  -webkit-backdrop-filter: blur(14px) saturate(150%);
          backdrop-filter: blur(14px) saturate(150%);
  color: var(--fg);
  font-family: var(--mono);
  font-size: .715rem;
  font-weight: 500;
  letter-spacing: .16em;
  text-transform: uppercase;
  white-space: nowrap;
  cursor: pointer;
  text-decoration: none;
  transition: border-color var(--fast) var(--ease-out),
              background var(--fast) var(--ease-out),
              color var(--fast) var(--ease-out);
}
.as-btn:hover, .as-btn:focus-visible { border-color: var(--accent); color: var(--accent); }
.as-btn:active { background: var(--wash); }       /* press, not release */
.as-btn--solid { background: var(--fg); color: var(--bg); border-color: var(--fg); }
.as-btn--solid:hover, .as-btn--solid:focus-visible { color: var(--bg); opacity: .88; }
.as-btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }

/* ── figure ── a number carries its source, or it is a claim (brand.md §5) ─ */
.as-figure { display: flex; flex-direction: column; gap: .35rem; }
.as-figure__value {
  font-family: var(--sans);
  font-size: clamp(2rem, 4vw, 2.9rem);
  font-weight: 800;
  letter-spacing: -.04em;
  line-height: 1;
  color: var(--fg);
}
.as-figure__label { font-size: .95rem; color: var(--muted); }
.as-figure__source {          /* the part that makes it evidence */
  font-family: var(--mono);
  font-size: .66rem;
  font-weight: 500;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: var(--faint);
}

@media (prefers-reduced-transparency: reduce) {
  .as-glass, .as-btn {
    -webkit-backdrop-filter: none; backdrop-filter: none;
    background: color-mix(in srgb, var(--fg) 9%, var(--bg));
  }
  .as-btn--solid { background: var(--fg); }
}
@media (prefers-contrast: more) {
  .as-glass, .as-btn { background: var(--bg); border-color: var(--fg); }
}
